-- builder AND an engineer review them. Rows are inserted as pending_review — NOTHING here is verified.
-- Run manually against the DATA STUDIO project (ovndokzwkxpfjfobewaq). Do NOT run on the RFQ/production project.
-- Idempotent: re-running skips systems that already exist for this manufacturer.
-- Optional: apply migration 069_deck_type.sql first so deck_type is set to 'subfloor' (this script sets it only if the column exists).

CREATE OR REPLACE FUNCTION pg_temp.ref_comp(p_mfr uuid, p_name text, p_cat text, p_uom text)
RETURNS uuid LANGUAGE plpgsql AS $f$
DECLARE v_id uuid;
BEGIN
  SELECT id INTO v_id FROM staged_components WHERE manufacturer_id = p_mfr AND name = p_name AND category IS NOT DISTINCT FROM p_cat LIMIT 1;
  IF v_id IS NULL THEN
    INSERT INTO staged_components (manufacturer_id, name, category, uom) VALUES (p_mfr, p_name, p_cat, p_uom) RETURNING id INTO v_id;
  END IF;
  RETURN v_id;
END $f$;

