    INSERT INTO staged_systems (manufacturer_id, source_document_id, name, product_code, category, subcategory, description, notes, custom_technical_attributes)
    VALUES (v_mfr, v_doc, 'Pedestal / Over-Slab Deck System', 'DWA-PED', 'Subfloor', 'Pedestal system', 'Generic RFQ template for a pedestal-supported deck or tile surface over an existing slab, paving or membrane. Slab falls, drainage, waterproofing, height, wind uplift and approvals must be checked by the builder/engineer before ordering.', 'Code DWA-PED. VARIABLES TO CONFIRM: Slab condition and falls; existing waterproofing membrane; drainage paths (do not block them); finished height vs door thresholds; load; wind uplift on exposed balconies; strata/body-corporate approval; whether it is over a habitable room (waterproofing, fire, engineering). OPEN QUESTIONS: [?] Which pedestal brands and height ranges are common in WA? [?] Typical joist spacing for the chosen board over pedestals? Standards referenced (paywalled — read at source, not reproduced): NCC 2022 Housing Provisions 2.2 and 3.4; AS 1684; AS/NZS 1604.1 (H3 above ground; H4/H5 ground contact); AS 3660.1 termite management; AS 3959 bushfire (BAL); AS/NZS 1170.1 imposed actions; AS 4312 atmospheric corrosivity (C1–C5, CX). Bushfire (BAL) overlay — AS 3959:2018 sets what the subfloor can be made from (secondary sources; confirm in the standard) [S]. BAL-12.5/19: unenclosed subfloor with members under 400 mm above ground needs bushfire-resisting timber or non-combustible members, or shielding/enclosure. BAL-29: unenclosed subfloor must meet BAL-29 clauses; verandah posts must be non-combustible or hardwood. BAL-40: post/column/stump clause not retrieved. Bushfire-resisting timbers are 750 kg/m3 or denser (Table E1). Add a BAL question to the order. STATUS: placeholder lists for builder + engineer review; not advice.', '[{"label": "Template type", "value": "Generic RFQ template \u2014 not manufacturer-certified"}, {"label": "Suits", "value": "Balconies, courtyards and slabs with an existing surface"}]'::jsonb)
    RETURNING id INTO v_sys;
