  IF NOT EXISTS (SELECT 1 FROM staged_systems WHERE manufacturer_id = v_mfr AND product_code = 'DWA-TSF-C') THEN
    SELECT id INTO v_doc FROM source_documents WHERE manufacturer_id = v_mfr AND source_url = 'https://gaa.com.au/corrosivity-environment-a-quick-guide/' LIMIT 1;
