    INSERT INTO staged_systems (manufacturer_id, source_document_id, name, product_code, category, subcategory, description, notes, custom_technical_attributes)
    VALUES (v_mfr, v_doc, 'Coastal Steel Deck Subframe', 'DWA-SSF-C', 'Subfloor', 'Steel subframe (coastal)', 'Generic RFQ template for a steel deck subframe near the coast. Coating system, thickness, fixings and details must be specified by the engineer against the site''s AS 4312 category. Generic RFQ template, not a manufacturer-certified system or engineering specification. Final sizes, grades, spacings, footings and compliance must be confirmed by the builder/engineer before ordering.', 'Code DWA-SSF-C. VARIABLES TO CONFIRM: AS 4312 category; coating system and DFT/zinc mass; fabrication details; fixings; maintenance and inspection interval; warranty terms of the steel/coating. OPEN QUESTIONS: [?] Is a duplex (galvanised + paint) coating standard practice for coastal decks in WA? [?] Who fabricates and coats steel deck frames locally? Standards referenced (paywalled — read at source, not reproduced): NCC 2022 Housing Provisions 2.2 and 3.4; AS 1684; AS/NZS 1604.1 (H3 above ground; H4/H5 ground contact); AS 3660.1 termite management; AS 3959 bushfire (BAL); AS/NZS 1170.1 imposed actions; AS 4312 atmospheric corrosivity (C1–C5, CX). Bushfire (BAL) overlay — AS 3959:2018 sets what the subfloor can be made from (secondary sources; confirm in the standard) [S]. BAL-12.5/19: unenclosed subfloor with members under 400 mm above ground needs bushfire-resisting timber or non-combustible members, or shielding/enclosure. BAL-29: unenclosed subfloor must meet BAL-29 clauses; verandah posts must be non-combustible or hardwood. BAL-40: post/column/stump clause not retrieved. Bushfire-resisting timbers are 750 kg/m3 or denser (Table E1). Add a BAL question to the order. STATUS: placeholder lists for builder + engineer review; not advice.', '[{"label": "Template type", "value": "Generic RFQ template \u2014 coastal variant of the steel subframe"}, {"label": "Corrosivity category", "value": "Confirm under AS 4312 for the exact lot"}, {"label": "Fixings", "value": "316 stainless or severe-duty coated; isolate stainless from carbon steel and aluminium [S]"}, {"label": "Coating", "value": "Per engineer (galvanising / duplex / stainless) \u2014 sources conflict on what is adequate in C5 [S]"}]'::jsonb)
    RETURNING id INTO v_sys;
