    INSERT INTO system_sources (manufacturer_id, staged_system_id, role, label, url, sort_order) VALUES (v_mfr, v_sys, 'tech_data', 'Hobson — Corrosion resistance note', 'https://cdn.hobson.com.au/documents/tech-corrosion-resistance-210825.pdf', 1) ON CONFLICT DO NOTHING;
    INSERT INTO system_sources (manufacturer_id, staged_system_id, role, label, url, sort_order) VALUES (v_mfr, v_sys, 'tech_data', 'GAA — Corrosivity environment quick guide', 'https://gaa.com.au/corrosivity-environment-a-quick-guide/', 2) ON CONFLICT DO NOTHING;
    INSERT INTO system_sources (manufacturer_id, staged_system_id, role, label, url, sort_order) VALUES (v_mfr, v_sys, 'tech_data', 'Simpson Strong-Tie — Corrosion protection for metal connectors', 'https://strongtie.com.au/node/1853', 3) ON CONFLICT DO NOTHING;
  END IF;

END $$;

-- Mark them as subfloor products if migration 069 (deck_type) has been applied.
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'staged_systems' AND column_name = 'deck_type') THEN
    EXECUTE 'UPDATE staged_systems SET deck_type = ''subfloor'' WHERE deck_type IS NULL AND manufacturer_id = (SELECT id FROM data_studio_manufacturers WHERE slug = ''buildquote-reference-systems'')';
  END IF;
END $$;

